using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> read(const fs::path&p,size_t n){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(n*8))throw std::runtime_error("Reference shape "+p.string());std::vector<double> v(n);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),n*8);return v;}
std::vector<double> rows(std::vector<double> v){auto r=v;for(size_t c=0;c<v.size()/9216;++c)for(size_t y=0;y<96;++y)for(size_t x=0;x<96;++x)r[c*9216+y*96+x]=v[c*9216+x*96+y];return r;}
int main(int argc,char**argv){try{if(argc!=5)throw std::invalid_argument("Usage: v10-runtime cpu-root log-validation-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],logRoot=argv[3],out=argv[4];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor,model.pyramid,model.comparison,model.jnd,model.csf,model.quality,model.logarithm);const auto lut=create_jnd_lut();size_t words=0;auto compare=[&](const std::vector<double>&a,const std::vector<double>&b,const std::string& name){if(a.size()!=b.size())throw std::runtime_error("Shape");for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i]))throw std::runtime_error(name+" bits at "+std::to_string(i));words+=a.size();};
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"})for(unsigned side=1;side<=2;++side){auto name=display+"_"+std::to_string(side),prefix=(cpu/native/name).string();auto lmsr=rows(read(prefix+"_clamped.f64",36864)),adapt=rows(read(prefix+"_adaptation.f64",9216));auto result=gpu.jnd(lut,lmsr,adapt);for(auto item:{std::pair{"post_pupil",&result.post_pupil},std::pair{"jnd",&result.channels},std::pair{"P",&result.response}}){compare(*item.second,rows(read(prefix+"_"+item.first+".f64",item.second->size())),item.first);std::ofstream f(out/(native+"_"+name+"_"+item.first+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(item.second->data()),item.second->size()*8);}compare({result.geometric_mean},read(prefix+"_geomean.f64",1),"CPU geo");compare({result.pupil_reduction},read(prefix+"_pupil_reduction.f64",1),"CPU pupil");}
 size_t nativeWords=words;for(unsigned seed=0;seed<5;++seed){std::vector<double> lmsr(36864,1.),adapt(9216,1.);auto table=lut;if(seed==1){for(size_t i=0;i<lmsr.size();++i)lmsr[i]=i%2?1e-12:1e12;}else if(seed==2){for(size_t i=0;i<lmsr.size();++i)lmsr[i]=.001+double((i/9216+1)*(i%97+1))*.13;for(size_t i=0;i<adapt.size();++i)adapt[i]=.1+double(i%83)*.17;}else if(seed==3){auto first=rgb_to_jnd_response_double(lut,lmsr,adapt,96,96,96.*96./30./30.,24);double query=std::log10(first.post_pupil[0]);auto it=std::upper_bound(table.log_luminance.begin(),table.log_luminance.end(),query);size_t k=std::clamp<size_t>(it-table.log_luminance.begin(),1,JND_LUT_SIZE-1)-1;if(k==0||k+1>=JND_LUT_SIZE)throw std::runtime_error("Control query outside interior");table.log_luminance[k]=query;}else if(seed==4){auto first=rgb_to_jnd_response_double(lut,lmsr,adapt,96,96,96.*96./30./30.,24);for(size_t i=0;i<lmsr.size();++i)lmsr[i]=std::pow(10.,lut.log_luminance[i%JND_LUT_SIZE])/first.pupil_reduction;}auto actual=gpu.jnd(table,lmsr,adapt),expected=rgb_to_jnd_response_double(table,lmsr,adapt,96,96,96.*96./30./30.,24);compare(actual.post_pupil,expected.post_pupil,"control post");compare(actual.channels,expected.channels,"control channels");compare(actual.response,expected.response,"control P");compare({actual.geometric_mean},{expected.geometric_mean},"control CPU geo");compare({actual.pupil_reduction},{expected.pupil_reduction},"control CPU pupil");}
 const auto input=read(logRoot/"fma_boundaries/run/input.f64",672036),oracle=read(logRoot/"octave_boundaries.f64",1344072);std::vector<double> logs;
 for(size_t offset=0;offset<input.size();offset+=36864){size_t n=std::min<size_t>(36864,input.size()-offset);auto values=gpu.logarithms(std::span<const double>(input).subspan(offset,n));logs.insert(logs.end(),values.begin(),values.end());}
 compare(logs,oracle,"GPU log API vs Octave");std::ofstream logDump(out/"logarithms.f64",std::ios::binary);logDump.write(reinterpret_cast<const char*>(logs.data()),logs.size()*8);logDump.close();
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid JND input accepted");};std::vector<double> lmsr(36864,1.),adapt(9216,1.);reject([&]{gpu.jnd(lut,{},adapt);});reject([&]{gpu.jnd(lut,lmsr,{});});lmsr[0]=0.;reject([&]{gpu.jnd(lut,lmsr,adapt);});lmsr[0]=1.;adapt[0]=-1.;reject([&]{gpu.jnd(lut,lmsr,adapt);});adapt[0]=1.;lmsr[0]=std::numeric_limits<double>::quiet_NaN();reject([&]{gpu.jnd(lut,lmsr,adapt);});lmsr[0]=1.;adapt[0]=std::numeric_limits<double>::infinity();reject([&]{gpu.jnd(lut,lmsr,adapt);});adapt[0]=1.;auto broken=lut;broken.log_luminance[1]=broken.log_luminance[0];reject([&]{gpu.jnd(broken,lmsr,adapt);});broken=lut;broken.cone[4]=std::numeric_limits<double>::quiet_NaN();reject([&]{gpu.jnd(broken,lmsr,adapt);});for(double value:{0.,-1.,std::numeric_limits<double>::denorm_min(),std::numeric_limits<double>::infinity(),std::numeric_limits<double>::quiet_NaN()}){std::vector<double> bad{value};reject([&]{gpu.logarithms(bad);});}reject([&]{gpu.logarithms({});});std::vector<double> large(36865,1.);reject([&]{gpu.logarithms(large);});
 std::ofstream(out/"PASS.txt")<<nativeWords<<" native hybrid JND Double words exact;"<<words-nativeWords<<" control plus log-API words exact;"<<rejected<<" rejection checks\n";std::cout<<words<<" hybrid JND/log-API words exact;GPU JND logs;CPU reduction/exp/pupil/slopes retained\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
